{
  "headline": "FDA's records trace our supply to plants with OAI classifications and Warning Letters within three years before the shortage posting",
  "headline_cites": ["D8", "D9", "D13", "D15", "D18", "D19"],
  "sentences": [
    {
      "text": "FDA first posted the bupivacaine hydrochloride shortage on 2018-02-20 and it remains current as of 2026-10-21.",
      "cites": ["E54", "D25"]
    },
    {
      "text": "Our Corvale Lakeside and Corvale General sites use product labeled by Hospira, Inc. from plants FEI 1021343 and FEI 1925262.",
      "cites": ["E8", "E5", "E6", "E22", "E34"]
    },
    {
      "text": "FDA inspection 976095 at FEI 1925262 ended 2016-06-08 and was classified OAI, 622 days before the shortage posting.",
      "cites": ["D8", "E28"]
    },
    {
      "text": "A Warning Letter was issued to FEI 1925262 on 2017-02-14, 371 days before the shortage posting.",
      "cites": ["D9", "E33"]
    },
    {
      "text": "FDA inspection 1064827 at FEI 1925262 ended 2018-08-15 and was classified OAI, with its classification letter dated 2020-04-22, 792 days after the posting.",
      "cites": ["D13", "D18", "E30"]
    },
    {
      "text": "FDA inspection 1106244 at Pfizer Healthcare India (FEI 3008316085) ended 2019-09-06 and was classified OAI, with its classification letter dated 2020-05-25, 825 days after the posting.",
      "cites": ["D15", "D19", "E40"]
    },
    {
      "text": "The rule‑ranked option is to transfer 19 units from Corvale Lakeside (20 days on hand) to Corvale East (9.3 days on hand), which would bring Corvale East to 10 days on hand.",
      "cites": ["D22", "D1", "D3"]
    }
  ]
}
